SCi = double(imread('exp1_fear_noisepattern.png'));sigma_b = 7;	%std of smoothing filterS_r = double(imread('average_face_mask_gray.png'));S_r = (S_r - min(S_r(:))) / (max(S_r(:))-min(S_r(:)));%01化掩码vecSCi = SCi(eq(S_r,0));Res = ZTransSCi(SCi,mean(vecSCi(:)),std(vecSCi(:)));Res.ZSCi = Res.ZSCi.*S_r;p = 0.05;	%p-valuetC = 2.7; 	%threshold (for Cluster test)Res = StatThresh(Res,p,sigma_b,tC,S_r);background = double(imread('average_face.jpg'));tCi = DiplayRes(Res,background);